func telegramChatIDMatches(configuredChatID, incomingChatID string) bool {
	cfgID := strings.TrimSpace(configuredChatID)
	incID := strings.TrimSpace(incomingChatID)
	if cfgID == "" || incID == "" {
		return true
	}
	return strings.EqualFold(cfgID, incID)
}
